:root{
  --paper:#eaf5fb;
  --sheet:#fff;
  --ink:#1f292d;
  --text:#35454c;
  --muted:#5f6f76;
  --soft:#7e8b90;
  --line:#d6dfe2;
  --line-soft:#e8edef;
  --accent:#355f57;
  --accent-soft:#edf6f3;
  --danger:#a5524c;
  --success:#477a6c;
  --shadow:0 18px 55px rgba(25,42,49,.14);
  --font:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif;
  --r-sm:8px;
  --r-md:12px;
  --r-lg:18px;
}
*{box-sizing:border-box}
html{
  min-height:100%;
  background:var(--paper) url("assets/pattern-v03.svg") repeat;
  color:var(--ink);
  font-family:var(--font);
  font-size:16px;
}
body{margin:0;min-height:100vh;background:transparent;overscroll-behavior-x:none}
button,input,textarea{font:inherit}
button{color:inherit}
button:focus-visible,input:focus-visible,a:focus-visible,textarea:focus-visible{
  outline:2px solid #6d9187;
  outline-offset:2px;
}
[hidden]{display:none}
.paper-shell{
  width:min(1240px,calc(100% - 96px));
  min-height:100vh;
  margin:0 auto;
  background:#fff;
  box-shadow:0 0 0 1px rgba(35,69,82,.06),0 0 34px rgba(39,92,117,.08);
}
.app-header{
  position:sticky;
  top:0;
  z-index:50;
  padding:10px 24px 8px;
  border-bottom:1px solid var(--line-soft);
  background:
    linear-gradient(to bottom,transparent 0 27px,rgba(110,143,157,.055) 27px 28px,transparent 28px 55px),
    rgba(255,255,255,.975);
  background-size:100% 28px;
  backdrop-filter:blur(14px);
}
.app-header:before{
  content:"";
  position:absolute;
  left:16px;
  top:0;
  bottom:0;
  width:1px;
  background:rgba(187,85,85,.14);
  pointer-events:none;
}
.notebook-head{
  position:relative;
  z-index:45;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:16px;
  margin-bottom:9px;
}
.brand-cluster,.status-cluster{display:flex;align-items:center;gap:11px}
.brand{display:inline-flex;align-items:center;gap:4px;padding:0;border:0;background:none;cursor:pointer}
.brand-rx{
  display:grid;place-items:center;
  width:34px;height:34px;
  border:1.5px solid #c64242;border-radius:8px;
  color:#c64242;font-size:14px;font-weight:780;
}
.brand-de{font-size:20px;font-weight:800;letter-spacing:-.04em}
.brand-copy{display:flex;flex-direction:column;gap:2px}
.brand-copy strong{font-size:13px;font-weight:700}
.brand-copy span{font-size:11px;color:var(--muted)}
.rate-stack{
  display:flex;flex-direction:column;gap:3px;
  padding-right:11px;border-right:1px solid var(--line-soft);
}
.rate-stack>div{display:grid;grid-template-columns:92px auto;align-items:baseline;gap:8px;line-height:1.15}
.rate-stack span{font-size:10px;color:var(--muted)}
.rate-stack strong,.rate-stack b{font-size:12px;font-weight:730;color:var(--text);font-variant-numeric:tabular-nums}
#headerCbrDate{font-size:10px;color:var(--muted);font-style:normal;font-weight:650}
#headerCbrDate.stale{color:#a97851}
.flip-date{
  width:60px;height:58px;
  display:grid;grid-template-rows:15px 29px 14px;
  align-items:center;text-align:center;overflow:hidden;
  border:1px solid #cfd9dd;border-radius:8px;background:#fff;
  box-shadow:0 3px 8px rgba(31,72,92,.06);
}
.flip-month{
  align-self:stretch;display:grid;place-items:center;
  background:#edf5f8;color:#50717f;
  font-size:10px;font-weight:760;letter-spacing:.08em;
}
.flip-day{font-size:21px;font-weight:770;color:#24363e}
.flip-year{font-size:10px;color:var(--muted)}
.header-question{
  height:40px;display:inline-flex;align-items:center;gap:7px;
  padding:0 10px;border:1px solid var(--line);border-radius:10px;
  background:#fff;color:#40565e;font-size:11px;font-weight:680;cursor:pointer;
}
.header-question svg,.dock-icon svg,.mobile-actions svg{
  fill:none;stroke:currentColor;stroke-width:1.6;
}
.header-question svg{width:17px;height:17px}

/* Universal order status */
.order-status-standard{
  box-sizing:border-box;
  min-width:154px;
  width:max-content;
  max-width:240px;
  min-height:48px;
  display:flex;
  flex-direction:column;
  align-items:flex-start;
  justify-content:center;
  gap:3px;
  padding:7px 12px;
  border:1px solid #cbd8dc;
  border-radius:12px;
  background:#f7fbfc;
  color:#304a54;
  font-variant-numeric:tabular-nums;
  font-feature-settings:"tnum" 1;
}
.order-status-meta{
  display:block;
  font-size:11px;
  line-height:1.05;
  font-weight:600;
  color:var(--muted);
  white-space:nowrap;
}
.order-status-total{
  display:block;
  font-size:15px;
  line-height:1.05;
  font-weight:800;
  color:var(--ink);
  white-space:nowrap;
}
.desktop-order-dock{
  position:relative;
  cursor:pointer;
  box-shadow:0 3px 10px rgba(43,78,91,.05);
  transition:border-color .16s ease,box-shadow .16s ease,background .16s ease,transform .16s ease;
}
.desktop-order-dock:hover{
  border-color:#8daeba;background:#f3f9fa;
  box-shadow:0 7px 20px rgba(43,78,91,.12);
}
.desktop-order-dock.has-order{background:#f4fafb}
.dock-hover-preview{
  position:absolute;
  right:0;top:calc(100% + 8px);
  width:370px;
  padding:10px;
  border:1px solid #cad7db;border-radius:12px;
  background:rgba(255,255,255,.99);
  box-shadow:0 16px 36px rgba(31,55,64,.16);
  opacity:0;visibility:hidden;transform:translateY(-4px);
  pointer-events:none;
  transition:opacity .14s ease,transform .14s ease,visibility .14s;
}
.desktop-order-dock:hover .dock-hover-preview,
.desktop-order-dock:focus-visible .dock-hover-preview{
  opacity:1;visibility:visible;transform:none;
}
.dock-preview-empty{padding:8px;color:var(--text);font-size:12px;text-align:left}
.dock-preview-line{
  display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:8px;
  align-items:center;padding:7px 2px;border-bottom:1px solid var(--line-soft);
  text-align:left;
}
.dock-preview-line span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px;font-weight:650}
.dock-preview-line small{font-size:11px;color:var(--muted);white-space:nowrap}
.dock-preview-line b{font-size:12px;white-space:nowrap}
.dock-preview-more{padding:6px 2px;font-size:11px;color:var(--muted);text-align:left}
.dock-preview-total{
  display:flex;align-items:baseline;justify-content:space-between;
  gap:10px;padding:8px 2px 2px;
  font-size:12px;font-weight:700;
}
.dock-preview-total b{font-size:15px}
.desktop-order-dock.order-accepted{animation:dockReceive .52s ease-out}
.desktop-order-dock.order-removed{animation:dockRemove .52s ease-out}
@keyframes dockReceive{
  0%{transform:scale(1)}
  38%{transform:scale(1.025);border-color:#709f90;box-shadow:0 0 0 5px rgba(82,142,122,.12)}
  100%{transform:scale(1)}
}
@keyframes dockRemove{
  0%{transform:scale(1)}
  38%{transform:scale(.985);border-color:#c79e9a;box-shadow:0 0 0 5px rgba(168,100,94,.09)}
  100%{transform:scale(1)}
}

/* Search */
.search-stage{position:relative;z-index:35}
.search-wrap{
  position:relative;display:flex;align-items:center;
  width:100%;height:52px;
  border:1px solid #c6d0d3;border-radius:13px;background:#fff;
  box-shadow:0 5px 18px rgba(30,36,39,.045);
}
.search-icon{
  position:absolute;left:14px;width:20px;height:20px;
  fill:none;stroke:#506267;stroke-width:1.7;pointer-events:none;
}
.search-input{
  width:100%;height:100%;padding:0 48px 0 44px;
  border:0;background:transparent;color:var(--ink);
  font-size:17px;font-weight:560;
}
.search-input::placeholder{color:#7e8b90}
.search-input:focus{outline:0}
.clear-search{
  position:absolute;right:8px;width:34px;height:34px;
  border:0;border-radius:8px;background:transparent;
  color:#6f7c81;font-size:24px;line-height:1;cursor:pointer;
}
.search-suggest{
  position:absolute;left:0;right:0;top:calc(100% + 5px);
  z-index:90;max-height:min(62vh,520px);overflow:auto;
  border:1px solid #c9d6da;border-radius:13px;background:rgba(255,255,255,.99);
  box-shadow:0 14px 34px rgba(31,55,64,.16);backdrop-filter:blur(14px);
}
.suggest-row{
  display:grid;grid-template-columns:minmax(0,1fr) 102px 40px;
  align-items:center;gap:9px;min-height:50px;
  padding:7px 9px 7px 12px;border-bottom:1px solid var(--line-soft);
}
.suggest-row:hover{background:#f6fafb}
.suggest-main{
  min-width:0;display:flex;flex-direction:column;align-items:flex-start;gap:4px;
  padding:0;border:0;background:transparent;text-align:left;cursor:pointer;
}
.suggest-main strong{
  max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
  font-size:13px;line-height:1.15;font-weight:730;
}
.suggest-main span{
  max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
  color:var(--muted);font-size:11px;
}
.suggest-price{display:flex;flex-direction:column;align-items:flex-end;gap:2px}
.suggest-price b{font-size:13px;font-weight:790;white-space:nowrap}
.suggest-price small{font-size:11px;color:var(--muted)}
.suggest-add{
  width:36px;height:36px;border:1px solid #c7d4d8;border-radius:9px;
  background:#fff;color:#294750;font-size:22px;cursor:pointer;
}
.suggest-add:hover{border-color:#80a99a;background:#f0f8f5}
.suggest-show-all{
  width:100%;min-height:42px;border:0;background:#f5f9fa;color:#365d6b;
  font-size:12px;font-weight:730;cursor:pointer;
}
.suggest-empty{padding:18px 12px;color:var(--text);font-size:12px}

/* Categories / context */
.category-strip{
  display:flex;flex-wrap:wrap;gap:7px;overflow:visible;
  width:100%;padding-top:7px;scrollbar-width:none;
}
.category-strip::-webkit-scrollbar,.subcategory-strip::-webkit-scrollbar{display:none}
.category-chip{
  flex:0 0 auto;min-height:32px;padding:0 11px;
  border:1px solid var(--line);border-radius:9px;background:#f8fafb;
  color:#465a62;font-size:11px;font-weight:610;cursor:pointer;
}
.category-chip.active{
  border-color:#82a8b7;background:#edf6f9;color:#244753;font-weight:730;
}
.workspace{padding:12px 24px 100px}
.context-line{
  display:flex;align-items:center;justify-content:space-between;
  min-height:30px;margin-bottom:4px;color:var(--muted);font-size:12px;
}
.context-line strong{color:var(--text);font-weight:720}
.subcategory-strip{
  display:flex;align-items:center;gap:7px;min-height:36px;
  overflow-x:auto;padding:2px 2px 5px;scrollbar-width:none;
}
.subcategory-label{flex:0 0 auto;color:var(--muted);font-size:11px;font-weight:680}
.subcategory-chip{
  flex:0 0 auto;min-height:30px;padding:0 10px;
  border:1px solid #d6e0e3;border-radius:8px;background:#fff;
  color:#53666e;font-size:11px;font-weight:620;cursor:pointer;
}
.subcategory-chip.active{border-color:#86aab7;background:#edf6f9;color:#284a57;font-weight:730}
.search-context-switch{
  display:flex;align-items:baseline;gap:9px;min-height:48px;
  padding:10px;border-bottom:1px solid #dce5e8;
}
.search-context-switch.category{
  border-left:3px solid #79a8b9;
  background:linear-gradient(90deg,rgba(226,242,248,.52),transparent 55%);
}
.search-context-switch.global,.search-context-switch.only{border-left:3px solid #d4dde0}
.context-current,.context-link{border:0;background:transparent;padding:0;font:inherit;text-align:left}
.context-current{font-size:15px;line-height:1.15;font-weight:800;color:#253c46;cursor:default}
.context-link{
  color:#4b6d79;font-size:12px;font-weight:680;text-decoration:underline;
  text-decoration-thickness:1px;text-underline-offset:3px;cursor:pointer;
}
.context-link:disabled{opacity:.45;cursor:default;text-decoration:none}
.context-separator{color:#b7c2c6;font-size:13px}
.search-context-switch + .search-result-group .search-group-head{display:none}
.search-result-group{margin:4px 0 12px}
.search-group-head{
  display:flex;align-items:flex-end;justify-content:space-between;gap:14px;
  min-height:46px;padding:8px;border-bottom:1px solid #dce5e8;
}
.search-group-head strong{font-size:14px;font-weight:760}
.search-group-head span,.search-group-head em{font-size:11px;color:var(--muted);font-style:normal}
.search-group-empty{padding:20px 8px;color:var(--text);font-size:12px}
.search-more,.load-more{
  display:block;margin:10px auto;padding:9px 14px;
  border:1px solid #d1dcdf;border-radius:9px;background:#fff;
  color:#48636e;font-size:12px;font-weight:690;cursor:pointer;
}

/* Product list */
.product-list{display:flex;flex-direction:column}
.product-row{
  position:relative;
  display:grid;
  grid-template-columns:54px minmax(300px,1fr) 120px 104px 132px;
  align-items:center;gap:13px;
  min-height:78px;padding:10px 8px;
  border-bottom:1px solid var(--line-soft);background:#fff;
  cursor:pointer;transition:background .12s ease;
}
.product-row:hover{background:#fafcfc}
.product-row.selected{background:#f7fbf9}
.product-row.selected:before{
  content:"";position:absolute;left:0;top:9px;bottom:9px;width:2px;
  border-radius:2px;background:#66847b;
}
.product-photo{
  width:48px;height:48px;display:grid;place-items:center;
  align-self:center;pointer-events:none;
}
.product-photo img{width:46px;height:46px;object-fit:contain}
.image-fallback{
  width:44px;height:44px;display:grid;place-items:center;
  border:1px solid var(--line);border-radius:8px;color:#7d8b90;font-size:17px;
}
.product-main{min-width:0}
.product-title-line{display:flex;align-items:center;gap:7px;min-width:0}
.product-title{
  min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
  font-size:15px;line-height:1.2;font-weight:700;letter-spacing:-.012em;
}
.rx-badge{
  flex:0 0 auto;padding:2px 4px;border:1px solid #c85252;border-radius:4px;
  color:#b94040;font-size:10px;font-weight:760;
}
.product-meta{
  display:flex;flex-wrap:wrap;gap:3px 5px;
  margin-top:5px;color:var(--muted);font-size:12px;line-height:1.35;
}
.meta-dot{display:inline-block;margin:0 5px;color:#88969b}
.details-link{
  display:inline-flex;align-items:center;margin-left:5px;
  color:#3e665d;text-decoration:none;font-size:11px;font-weight:680;
}
.details-link:hover{text-decoration:underline}
.product-price,.product-total{
  display:flex;flex-direction:column;align-items:flex-end;gap:2px;white-space:nowrap;
}
.product-price strong,.product-total strong{font-size:16px;font-weight:770;font-variant-numeric:tabular-nums}
.product-price span,.product-total span{color:var(--muted);font-size:12px;font-weight:520}
.product-price small{order:-1;color:var(--muted);font-size:11px}
.qty-stepper{
  display:grid;grid-template-columns:32px 38px 32px;
  width:102px;height:36px;overflow:hidden;
  border:1px solid #c9d2d4;border-radius:8px;background:#fff;
  cursor:default;
}
.qty-stepper button,.qty-stepper input{
  height:34px;margin:0;padding:0;border:0;background:#f5f7f7;text-align:center;
}
.qty-stepper button{font-size:18px;cursor:pointer}
.qty-stepper button:disabled{color:#aeb9bd;cursor:default}
.qty-stepper input{
  width:38px;border-left:1px solid #e0e6e8;border-right:1px solid #e0e6e8;
  background:#fff;font-size:13px;font-weight:760;
}
.qty-stepper input::-webkit-outer-spin-button,.qty-stepper input::-webkit-inner-spin-button{-webkit-appearance:none;margin:0}
.product-total.empty{color:var(--muted)}
.product-total.empty span{max-width:105px;text-align:right;white-space:normal;line-height:1.2}
.order-jump{
  margin-top:4px;padding:0;border:0;background:none;color:#486a62;
  font-size:11px;font-weight:700;cursor:pointer;
}
.order-jump:hover{text-decoration:underline}
.product-expand{
  grid-column:2/-1;display:none;
  padding:12px 0 10px;border-top:1px dotted #d9e2e4;
  color:var(--text);font-size:12px;line-height:1.45;cursor:default;
}
.product-row.expanded .product-expand{display:block}
.expand-visual{display:grid;grid-template-columns:92px minmax(0,1fr);gap:14px}
.expand-visual>img{width:86px;height:86px;object-fit:contain}
.expand-grid{display:grid;grid-template-columns:repeat(2,minmax(150px,1fr));gap:10px 20px}
.expand-item span{display:block;color:var(--muted);font-size:11px;font-weight:650}
.expand-item b{display:block;margin-top:2px;color:var(--text);font-size:13px;font-weight:700}
.expand-actions{display:flex;gap:14px;margin-top:11px}
.expand-actions a,.return-order-link{
  color:#365f55;font-size:12px;font-weight:700;text-decoration:none;
}
.expand-actions a:hover,.return-order-link:hover{text-decoration:underline}
.return-order-link{border:0;background:transparent;padding:0;cursor:pointer}

/* Deletion */
.product-row.pending-delete,.order-line.pending-delete,.order-product-row.pending-delete{position:relative;z-index:1}
.product-row.pending-delete:after,.order-line.pending-delete:after,.order-product-row.pending-delete:after{
  content:"";position:absolute;inset:3px 0;z-index:4;
  background:
    repeating-linear-gradient(17deg,rgba(162,62,62,.02) 0 13px,rgba(162,62,62,.27) 13px 14px),
    repeating-linear-gradient(-17deg,transparent 0 13px,rgba(162,62,62,.22) 13px 14px),
    rgba(255,250,248,.80);
  pointer-events:none;
}
.delete-overlay{
  position:absolute;inset:0;z-index:20;
  display:flex;align-items:center;justify-content:center;
  pointer-events:none;
}
.delete-card{
  display:flex;align-items:center;gap:12px;
  max-width:calc(100% - 18px);padding:9px 12px;
  border:1px solid #d9c0bc;border-radius:10px;background:rgba(255,255,255,.98);
  box-shadow:0 8px 25px rgba(70,40,35,.12);pointer-events:auto;
}
.delete-card span{font-size:12px;color:#704d49}
.delete-card b{font-size:14px}
.delete-card button{
  height:32px;padding:0 10px;border:1px solid #cfd3d1;border-radius:7px;
  background:#fff;font-size:11px;font-weight:760;cursor:pointer;
}

/* Order sheet */
.sheet-backdrop,.confirm-backdrop{
  position:fixed;inset:0;z-index:100;
  background:rgba(22,31,35,.62);backdrop-filter:blur(3px);
}
.order-sheet{
  position:absolute;left:50%;top:4vh;transform:translateX(-50%);
  display:flex;flex-direction:column;
  width:min(980px,calc(100vw - 28px));height:min(92vh,820px);overflow:hidden;
  border:1px solid #ccd7da;border-radius:18px;background:
    linear-gradient(to bottom,transparent 0 31px,rgba(113,147,160,.045) 31px 32px,transparent 32px 63px),
    #fff;
  background-size:100% 32px;box-shadow:var(--shadow);
}
.sheet-header{
  position:relative;display:flex;align-items:flex-start;justify-content:space-between;
  padding:18px 20px 12px 30px;border-bottom:1px solid var(--line-soft);
}
.sheet-header:before{
  content:"";position:absolute;left:20px;top:0;bottom:0;width:1px;background:rgba(191,92,92,.16)
}
.sheet-kicker{font-size:10px;font-weight:760;letter-spacing:.12em;color:#62818d}
.sheet-header h2,.confirm-card h2{margin:3px 0 0;font-size:22px;line-height:1.1;letter-spacing:-.03em}
.sheet-header p{margin:5px 0 0;color:var(--muted);font-size:12px}
.sheet-close,.confirm-close{
  width:34px;height:34px;border:0;background:none;color:#627177;font-size:28px;cursor:pointer;
}
.sheet-toolbar{
  display:flex;align-items:center;justify-content:space-between;
  min-height:46px;padding:7px 20px;border-bottom:1px solid var(--line-soft);
}
.sheet-toolbar-left{display:flex;align-items:center;gap:8px}
.text-button{padding:5px 8px;border:0;background:none;color:#355a52;font-size:12px;font-weight:700;cursor:pointer}
.danger-soft{color:#8d5954}
.danger-soft.armed{
  color:#a04740;background:#fff2f0;border:1px solid #e3c5c1;border-radius:7px;padding:5px 9px;
}
.rate-note{font-size:11px;color:var(--muted)}
.rate-note b{font-size:12px;color:var(--text)}
.order-lines{
  flex:1;min-height:0;overflow:auto;padding:2px 20px;
  overscroll-behavior:contain;
}
.order-line{
  position:relative;
  display:grid;grid-template-columns:28px 48px minmax(240px,1fr) 110px 104px 128px 30px;
  align-items:center;gap:10px;min-height:76px;padding:9px 0;border-bottom:1px solid var(--line-soft);
  cursor:pointer;
}
.order-line:hover{background:#fafcfc}
.order-line.logistics-line{cursor:default;background:#fbfcfc}
.order-line.logistics-line:hover{background:#fbfcfc}
.order-num{font-size:11px;font-weight:760;color:var(--muted);text-align:center}
.order-product-link,.compact-product-link{
  border:0;background:transparent;padding:0;color:inherit;text-align:left;cursor:pointer;
}
.order-product-link{
  min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
  font-size:15px;line-height:1.2;font-weight:720;
}
.order-product-link:hover,.compact-product-link:hover{text-decoration:underline;text-underline-offset:3px}
.order-delete{width:28px;height:28px;border:0;background:none;color:#9f625d;font-size:19px;cursor:pointer}
.compact-line{
  display:block;
  border-bottom:1px solid var(--line-soft);
  padding:7px 0;
}
.compact-main{display:grid;gap:5px}
.compact-head{
  display:grid;
  grid-template-columns:minmax(0,1fr) auto;
  align-items:start;
  gap:10px;
}
.compact-name{
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
  font-size:13px;
  line-height:1.2;
  font-weight:680;
}
.compact-foot{
  display:grid;
  grid-template-columns:minmax(0,1fr) auto;
  align-items:center;
  gap:10px;
}
.compact-unit{font-size:11px;color:var(--text);white-space:nowrap}
.compact-actions{display:flex;align-items:center;gap:10px;justify-content:flex-end}
.compact-more{
  display:none;
  padding:0;
  border:0;
  background:none;
  color:#355a52;
  font-size:11px;
  font-weight:700;
  cursor:pointer;
  white-space:nowrap;
}
.compact-more:hover{text-decoration:underline;text-underline-offset:3px}
.compact-rub{font-size:13px;font-weight:790;white-space:nowrap;text-align:right}

.sheet-footer{
  display:grid;grid-template-columns:1fr minmax(280px,420px);
  align-items:center;gap:18px;padding:12px 20px;
  border-top:1px solid var(--line);background:#fff;
}
.order-summary{display:flex;align-items:end;gap:12px}
.order-summary span{font-size:12px;font-weight:680;color:var(--text)}
.order-summary strong{
  font-size:29px;line-height:1;font-weight:700;letter-spacing:-.02em;
  font-variant-numeric:tabular-nums;font-feature-settings:"tnum" 1;
}
.order-summary small{font-size:11px;color:var(--muted)}
.primary-action{
  min-height:48px;display:flex;align-items:center;justify-content:space-between;
  padding:0 16px;border:0;border-radius:11px;background:var(--accent);
  color:#fff;font-size:13px;font-weight:720;cursor:pointer;
}
.primary-action.full{width:100%}

/* Confirm */
.confirm-card{
  position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);
  display:flex;flex-direction:column;
  width:min(540px,calc(100vw - 28px));max-height:min(88vh,760px);
  overflow:hidden;padding:20px;border:1px solid #d4dcde;border-radius:16px;background:#fff;
  box-shadow:var(--shadow);
}
.confirm-close{position:absolute;right:12px;top:10px}
.mini-receipt{
  flex:1;min-height:120px;max-height:min(48vh,480px);
  overflow-y:auto;margin:14px 0;padding:10px 12px;
  border:1px solid var(--line);border-radius:10px;background:#fbfcfc;
}
.mini-row{
  display:grid;grid-template-columns:minmax(0,1fr) auto;
  gap:8px;min-height:34px;align-items:center;padding:5px 0;
  border-bottom:1px dotted #dfe5e7;font-size:12px;
}
.mini-row b{font-size:12px;font-weight:720}
.mini-total{
  position:sticky;bottom:0;
  display:flex;justify-content:space-between;align-items:baseline;
  margin-top:9px;padding:10px 0 4px;border-top:1px solid var(--line);
  background:#fff;
}
.mini-total strong{font-size:20px}
.phone-field{display:flex;flex-direction:column;gap:6px;margin:12px 0;color:var(--text);font-size:12px;font-weight:650}
.phone-field input{height:44px;padding:0 12px;border:1px solid #cdd5d8;border-radius:9px;background:#fff;font-size:15px}
.confirm-note{margin:8px 0 0;color:var(--muted);font-size:11px;text-align:center}

/* Question */
.question-backdrop{
  position:fixed;inset:0;z-index:120;
  background:rgba(21,31,36,.58);backdrop-filter:blur(3px);
}
.question-sheet{
  position:absolute;right:max(18px,calc((100vw - 1240px)/2 + 18px));top:78px;
  width:min(430px,calc(100vw - 28px));overflow:hidden;
  border:1px solid #cfdbdf;border-radius:18px;
  background:#f5fbfe url("assets/pattern-v03.svg") repeat;background-size:390px 390px;
  box-shadow:0 20px 60px rgba(25,47,58,.2);
}
.question-head{
  display:grid;grid-template-columns:40px 1fr 34px;gap:10px;align-items:start;
  padding:14px;background:rgba(255,255,255,.95);border-bottom:1px solid #dbe5e8;
}
.question-head h2{margin:2px 0 3px;font-size:19px}
.question-head p{margin:0;color:var(--muted);font-size:12px}
.messenger-avatar{
  width:38px;height:38px;display:grid;place-items:center;
  border:1px solid #cf4b4b;border-radius:50%;background:#fff;color:#c84545;
  font-size:12px;font-weight:800;
}
.chat-paper{padding:18px 14px 12px}
.chat-bubble{
  max-width:84%;padding:10px 12px;border-radius:13px 13px 13px 4px;background:#fff;
  color:var(--text);font-size:12px;line-height:1.45;box-shadow:0 2px 7px rgba(55,86,98,.08);
}
.chat-compose{display:block;margin-top:14px}
.chat-compose textarea{
  width:100%;min-height:104px;resize:vertical;padding:12px;
  border:1px solid #ccdade;border-radius:14px;background:rgba(255,255,255,.97);
  color:var(--ink);font-size:13px;line-height:1.45;
}
.question-footer{display:flex;justify-content:flex-end;padding:10px 14px 14px}
.messenger-send{
  min-height:42px;display:inline-flex;align-items:center;gap:8px;padding:0 14px;
  border:0;border-radius:12px;background:#4f96b4;color:#fff;font-size:12px;font-weight:720;cursor:pointer;
}
.messenger-send svg{width:17px;height:17px;fill:none;stroke:currentColor;stroke-width:1.6}

/* Admin */
.admin-backdrop{position:fixed;inset:0;z-index:140;background:rgba(18,28,33,.65);backdrop-filter:blur(3px)}
.admin-sheet{
  position:absolute;left:50%;top:3vh;transform:translateX(-50%);
  width:min(980px,calc(100vw - 24px));max-height:94vh;overflow:auto;
  border:1px solid #cad8dd;border-radius:18px;
  background:#f8fcfe url("assets/pattern-v03.svg") repeat;background-size:520px 520px;
  box-shadow:0 24px 70px rgba(15,36,47,.25);
}
.admin-head{
  display:grid;grid-template-columns:42px 1fr 36px;gap:11px;align-items:start;
  padding:16px 18px;background:rgba(255,255,255,.96);border-bottom:1px solid #dbe5e8;
}
.admin-head h2{margin:2px 0 3px;font-size:20px}
.admin-head p{margin:0;color:var(--muted);font-size:12px}
.admin-mark{
  width:40px;height:40px;display:grid;place-items:center;
  border:1px solid #6f9aac;border-radius:10px;background:#edf7fb;color:#446b7b;
  font-size:15px;font-weight:800;
}
.admin-body{padding:14px}
.admin-input-block,.admin-result-block{
  padding:14px;border:1px solid rgba(159,184,194,.55);border-radius:14px;
  background:rgba(255,255,255,.96);box-shadow:0 5px 18px rgba(49,82,96,.06);
}
.admin-result-block{margin-top:12px}
.admin-block-head{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:8px}
.admin-block-head strong{font-size:13px}
.admin-block-head span{color:var(--muted);font-size:11px}
.admin-source,.admin-address-label textarea{
  width:100%;padding:11px 12px;border:1px solid #ccdadd;border-radius:10px;
  background:#fff;color:var(--text);font-size:12px;line-height:1.45;resize:vertical;
}
.admin-main-action,.admin-secondary-action{
  min-height:40px;padding:0 13px;border-radius:10px;font-size:12px;font-weight:720;cursor:pointer;
}
.admin-main-action{margin-top:9px;border:0;background:#376f66;color:#fff}
.admin-secondary-action{border:1px solid #c9d6da;background:#fff;color:#46616c}
.admin-detected{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-bottom:12px}
.admin-detected>div{padding:8px 9px;border:1px solid #e1e8ea;border-radius:9px;background:#fbfdfe}
.admin-detected span{display:block;color:var(--muted);font-size:11px}
.admin-detected strong{display:block;margin-top:3px;font-size:12px}
.admin-items{display:flex;flex-direction:column;border-top:1px solid #e4eaec}
.admin-item{
  display:grid;grid-template-columns:minmax(0,1fr) 140px 50px;
  align-items:center;gap:10px;min-height:56px;padding:8px 2px;border-bottom:1px solid #e8edef;
}
.admin-item b{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px}
.admin-item span{display:block;margin-top:3px;color:var(--muted);font-size:11px}
.admin-item em{justify-self:end;font-style:normal;font-size:13px;font-weight:760}
.admin-price-compare{text-align:right}
.admin-price-compare small{display:block;color:#8e6f6c;font-size:11px}
.admin-price-compare strong{font-size:12px}
.admin-address-label{display:block;margin-top:12px}
.admin-address-label>span{display:flex;justify-content:space-between;align-items:center;margin-bottom:5px;font-size:12px;font-weight:700}
.admin-address-label small{display:block;margin-top:5px;color:var(--muted);font-size:11px}
.admin-result-actions{display:flex;gap:8px;margin-top:10px}
.admin-result-actions .admin-main-action{margin-top:0}
.admin-preview-wrap{margin-top:14px}
.admin-preview{
  max-height:300px;overflow:auto;margin:0;padding:11px;border:1px solid #dce5e8;border-radius:10px;
  background:#fbfcfc;color:var(--text);font:12px/1.45 ui-monospace,SFMono-Regular,Consolas,monospace;white-space:pre-wrap;
}
.admin-empty{padding:18px;color:var(--muted);font-size:12px;text-align:center}

/* Common */
.toast{
  position:fixed;left:50%;bottom:24px;z-index:200;transform:translateX(-50%);
  padding:9px 13px;border:1px solid #cdd6d8;border-radius:9px;background:#fff;
  color:var(--text);box-shadow:0 10px 30px rgba(20,27,30,.15);font-size:12px;
}
.order-fly-ghost{
  position:fixed;z-index:999;width:34px;height:28px;display:grid;place-items:center;
  margin:-14px 0 0 -17px;border:1px solid #91aaa4;border-radius:8px;
  background:rgba(255,255,255,.97);color:#3f6a5f;box-shadow:0 5px 16px rgba(45,83,73,.18);
  pointer-events:none;transition:transform .48s cubic-bezier(.2,.7,.2,1),opacity .42s ease;
}
.order-fly-ghost span{font-size:16px;font-weight:760}
.bridge-highlight{animation:bridgeHighlight .9s ease-out}
@keyframes bridgeHighlight{
  0%{box-shadow:inset 0 0 0 2px rgba(82,133,116,.42);background:#eef8f4}
  100%{box-shadow:inset 0 0 0 0 rgba(82,133,116,0)}
}
.mobile-actions{display:none}

