/* v0.61 — canonical layer map. Do not assign ad-hoc z-index values outside this scale. */
:root{
  --z-content:1;
  --z-sticky-nav:40;
  --z-header:50;
  --z-search:70;
  --z-dropdown:80;
  --z-order-preview:90;
  --z-modal:100;
  --z-modal-overlay:120;
  --z-toast:200;
}

/* Header is one stacking context. Keep the order/status row above the search row so
   its mini receipt can never be hidden by search/scope/suggestion layers. */
.app-header{z-index:var(--z-header)!important;overflow:visible!important}
.notebook-head{z-index:var(--z-order-preview)!important;overflow:visible!important}
.search-stage{z-index:var(--z-search)!important;overflow:visible!important}
.search-wrap{z-index:var(--z-search)!important}
.search-suggest,.search-scope-menu{z-index:var(--z-dropdown)!important}
.flow-nav:not([hidden]){z-index:var(--z-sticky-nav)!important}
.flow-history-menu{z-index:var(--z-dropdown)!important}

/* Order mini receipt must sit above all header dropdowns. */
.desktop-order-dock{z-index:1!important;overflow:visible!important}
.dock-hover-preview{
  z-index:var(--z-order-preview)!important;
  isolation:isolate;
}

/* Modal family always wins over the complete sticky header. */
.sheet-backdrop,.confirm-backdrop,.question-backdrop{z-index:var(--z-modal)!important}
.delete-backdrop,.delete-card,.toast{z-index:var(--z-modal-overlay)!important}

/* Avoid accidental clipping of header popovers introduced by future layout rules. */
.status-cluster,.brand-cluster{overflow:visible!important}
nn/* ===== v0.62: final order dock + flip calendar ===== */
/* The top-right order status is now click-only. No hover receipt/popover. */
.dock-hover-preview{display:none!important}

/* Calendar: small paper object tied visually to the RX red accent. */
.flip-date{
  position:relative;
  overflow:visible!important;
  width:60px;height:60px;
  grid-template-rows:16px 29px 15px;
  border:1px solid rgba(198,66,66,.52)!important;
  border-radius:9px!important;
  background:#fff!important;
  box-shadow:0 4px 10px rgba(72,51,51,.10),0 1px 2px rgba(72,51,51,.08)!important;
  isolation:isolate;
  transform:translateZ(0);
}
.flip-date::before,
.flip-date::after{
  content:"";
  position:absolute;
  z-index:-2;
  inset:3px -4px -4px 4px;
  border:1px solid rgba(198,66,66,.18);
  border-radius:8px;
  background:#fff;
}
.flip-date::after{
  z-index:-1;
  inset:1px -2px -2px 2px;
  background:#fffafa;
}
.flip-month{
  position:relative;
  z-index:2;
  background:linear-gradient(180deg,#d95a58,#c64242)!important;
  color:#fff!important;
  border-radius:8px 8px 0 0;
  font-size:10px!important;
  font-weight:800!important;
  letter-spacing:.09em!important;
  text-shadow:0 1px 0 rgba(80,0,0,.12);
}
.flip-month::before,
.flip-month::after{
  content:"";
  position:absolute;
  top:-4px;
  width:4px;height:8px;
  border-radius:3px;
  background:#f7f9f9;
  box-shadow:0 0 0 1px rgba(91,105,110,.16);
}
.flip-month::before{left:14px}.flip-month::after{right:14px}
.flip-day{
  position:relative;
  z-index:1;
  display:grid;place-items:center;
  height:100%;
  background:#fff;
  color:#24363e!important;
  font-variant-numeric:tabular-nums;
  transform-origin:50% 0%;
  backface-visibility:hidden;
}
.flip-year{
  position:relative;
  z-index:2;
  align-self:stretch;
  display:grid;place-items:center;
  background:linear-gradient(180deg,#fff,#fff8f7);
  border-radius:0 0 8px 8px;
}
.flip-date .flip-corner{display:none}
.flip-date::selection{background:transparent}
.flip-date.is-flipping .flip-day{
  animation:rxde-calendar-flip .31s cubic-bezier(.24,.75,.36,1);
}
@keyframes rxde-calendar-flip{
  0%{transform:perspective(180px) rotateX(0deg);filter:brightness(1)}
  46%{transform:perspective(180px) rotateX(-78deg);filter:brightness(.94)}
  47%{opacity:.15}
  52%{transform:perspective(180px) rotateX(38deg);opacity:.35}
  100%{transform:perspective(180px) rotateX(0deg);opacity:1;filter:brightness(1)}
}
/* folded lower corner, deliberately subtle */
.flip-date{--fold:9px}
.flip-date > .flip-year::after{
  content:"";
  position:absolute;
  right:0;bottom:0;
  width:var(--fold);height:var(--fold);
  border-radius:0 0 7px 0;
  background:linear-gradient(135deg,rgba(198,66,66,.08) 0 48%,#ead8d6 49% 52%,#fff 53% 100%);
  pointer-events:none;
}
@media (max-width:760px){
  .flip-date{width:48px!important;height:50px!important;grid-template-rows:13px 25px 12px!important;border-radius:8px!important}
  .flip-month{font-size:9px!important;border-radius:7px 7px 0 0!important}
  .flip-month::before{left:11px}.flip-month::after{right:11px}
  .flip-day{font-size:20px!important}
  .flip-year{font-size:9px!important}
}

/* Final manager check: one accounting-like row model everywhere. */
.mini-row{
  display:grid!important;
  grid-template-columns:minmax(0,1fr) auto!important;
  gap:14px!important;
  align-items:center!important;
}
.mini-row .mini-main{min-width:0}
.mini-row .mini-title{display:flex;align-items:baseline;gap:7px;min-width:0}
.mini-row .mini-name{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.mini-row .mini-calc{display:block;margin-top:3px;font-size:12px;color:var(--muted);font-variant-numeric:tabular-nums;white-space:nowrap}
.mini-row>strong{font-variant-numeric:tabular-nums;white-space:nowrap}
@media (max-width:760px){
  .mini-row{grid-template-columns:minmax(0,1fr) auto!important;gap:9px!important}
  .mini-row .mini-calc{font-size:11px}
}


/* v0.63.2 — quiet rate-update leaf turn. */
.flip-date.rate-check-flip .flip-day{animation:rxdeRateLeaf .48s cubic-bezier(.22,.75,.2,1)}
@keyframes rxdeRateLeaf{
  0%{transform:perspective(420px) rotateX(0deg) translateY(0);filter:brightness(1)}
  42%{transform:perspective(420px) rotateX(-15deg) translateY(-1px);filter:brightness(1.025)}
  100%{transform:perspective(420px) rotateX(0deg) translateY(0);filter:brightness(1)}
}
@media (prefers-reduced-motion:reduce){.flip-date.rate-check-flip .flip-day{animation:none}}


/* v0.64 — compact no-layout-shift calendar. Same visual height as order status. */
.flip-date{width:46px!important;height:46px!important;grid-template-rows:13px 33px!important;border-radius:8px!important;contain:layout paint}
.flip-month{font-size:8.5px!important;border-radius:7px 7px 0 0!important}
.flip-month::before{left:10px!important}.flip-month::after{right:10px!important}
.flip-day{font-size:20px!important;border-radius:0 0 7px 7px!important}
.flip-year{display:none!important}.flip-date > .flip-year::after{display:none!important}
@media(max-width:760px){.flip-date{width:42px!important;height:42px!important;grid-template-rows:12px 30px!important}.flip-day{font-size:18px!important}}


/* ===== v0.65 — zero-layout-shift nav, elapsed-days calendar, explicit row delete ===== */
/* The navigation bar exists in the first HTML layout. JS only fills its content. */
.flow-nav.nav-booting > *{visibility:hidden!important}

/* Do not show a placeholder 00 while JS resolves the local date. */
.flip-day:not(.date-ready){color:transparent!important}

/* A real paper leaf overlays the fixed-size calendar; flipping never changes layout. */
.flip-date{perspective:520px!important;overflow:visible!important;contain:layout paint!important}
.flip-leaf{
  position:absolute;inset:0;z-index:8;display:grid;grid-template-rows:13px 33px;
  border:1px solid rgba(198,66,66,.52);border-radius:8px;background:#fff;
  box-shadow:0 5px 10px rgba(72,51,51,.12);transform-origin:50% 0%;
  opacity:0;pointer-events:none;overflow:hidden;backface-visibility:hidden;
}
.flip-leaf-month{display:grid;place-items:center;background:linear-gradient(180deg,#d95a58,#c64242);color:#fff;font-size:8.5px;font-weight:800;letter-spacing:.09em}
.flip-leaf-day{position:relative;display:grid;place-items:center;background:#fff;color:#24363e;font-size:20px;font-weight:770;font-variant-numeric:tabular-nums}
.flip-leaf::before,.flip-leaf::after{content:"";position:absolute;pointer-events:none}
/* curling/folded lower-right paper corner — grows while the sheet turns */
.flip-leaf::after{right:0;bottom:0;width:13px;height:13px;z-index:12;background:linear-gradient(135deg,transparent 0 45%,#e8cecb 46% 51%,#fff6f5 52% 100%);clip-path:polygon(0 100%,100% 0,100% 100%);transform-origin:100% 100%;opacity:.25}
.flip-leaf::before{left:7px;right:7px;bottom:2px;height:4px;border-radius:50%;background:rgba(75,42,42,.12);filter:blur(2px);opacity:0}
.flip-leaf.turning{opacity:1;animation:rxdeElapsedLeaf .70s cubic-bezier(.25,.72,.25,1) both}
.flip-leaf.turning::after{animation:rxdeFoldCorner .70s ease-in-out both}
.flip-leaf.turning::before{animation:rxdeLeafShadow .70s ease-in-out both}
@keyframes rxdeElapsedLeaf{
  0%{transform:perspective(520px) rotateX(0deg) translateY(0);opacity:1;filter:brightness(1)}
  28%{transform:perspective(520px) rotateX(-28deg) translateY(-1px);opacity:1;filter:brightness(1.02)}
  62%{transform:perspective(520px) rotateX(-88deg) translateY(3px);opacity:.92;filter:brightness(.94)}
  100%{transform:perspective(520px) rotateX(-116deg) translateY(8px);opacity:0;filter:brightness(.90)}
}
@keyframes rxdeFoldCorner{0%{transform:scale(.45);opacity:.18}42%{transform:scale(1.45) rotate(5deg);opacity:.9}100%{transform:scale(.8) rotate(10deg);opacity:.25}}
@keyframes rxdeLeafShadow{0%{opacity:0;transform:scaleX(.7)}55%{opacity:.7;transform:scaleX(1)}100%{opacity:0;transform:scaleX(.75)}}
@media(max-width:760px){.flip-leaf{grid-template-rows:12px 30px}.flip-leaf-month{font-size:8px}.flip-leaf-day{font-size:18px}}
@media(prefers-reduced-motion:reduce){.flip-leaf{display:none!important}}

