/* ===== v0.69 — warm active order row + restrained paper depth ===== */
.order-product-row{
  position:relative;
  transition:background-color .14s ease, box-shadow .14s ease, transform .14s ease, border-color .14s ease;
  transform-origin:center center;
}

/* Mouse/trackpad only: the active line becomes a slightly richer sheet of paper. */
@media (hover:hover) and (pointer:fine){
  .order-product-row:hover{
    background:#f8edcf!important;
    box-shadow:
      0 7px 13px rgba(83,67,39,.075),
      0 1px 2px rgba(83,67,39,.08),
      inset 0 1px 0 rgba(255,255,255,.72);
    transform:translateY(-1px) scale(1.0015);
    z-index:4;
  }
  .order-product-row:hover .order-thumb{
    background:#fffaf0!important;
    box-shadow:0 3px 8px rgba(83,67,39,.06);
  }
  .order-product-row:hover .order-num-badge{
    box-shadow:0 3px 7px rgba(24,117,171,.16);
  }
}

/* Keyboard focus gets the same location cue without movement. */
.order-product-row:focus-within{
  background:#f8edcf;
}

/* Do not create hover/lift artefacts on touch devices. */
@media (hover:none), (pointer:coarse), (max-width:760px){
  .order-product-row,
  .order-product-row:hover,
  .order-product-row:focus-within{
    transform:none!important;
    box-shadow:none!important;
  }
  .order-product-row:focus-within{
    background:#f8edcf!important;
  }
}

@media (prefers-reduced-motion:reduce){
  .order-product-row{transition:none!important}
  .order-product-row:hover{transform:none!important}
}

/* ===== v0.70 — fixed notebook paper, guaranteed PZN row, unnumbered DHL ===== */
/* The notebook ruling belongs to the sheet. Product rows never translate/scale over it. */
.order-product-row{
  transform:none!important;
  transform-origin:initial!important;
  transition:background-color .12s ease,box-shadow .12s ease,border-color .12s ease!important;
}
@media (hover:hover) and (pointer:fine){
  .order-product-row:hover{
    background:#f8edcf!important;
    transform:none!important;
    box-shadow:inset 0 1px 0 rgba(255,255,255,.66),inset 0 -1px 0 rgba(157,133,91,.10)!important;
    z-index:auto!important;
  }
  .order-product-row:hover .order-thumb{
    background:#fffaf0!important;
    box-shadow:none!important;
  }
  .order-product-row:hover .order-num-badge{
    box-shadow:0 2px 6px rgba(8,120,183,.18)!important;
  }
}
.order-product-row:focus-within{background:#f8edcf!important;transform:none!important;box-shadow:none!important}

/* Order identity uses three stable reading lines: name / form+maker / PZN. */
.order-product-info{align-self:center;min-width:0}
.order-meta{
  display:block!important;
  margin-top:4px!important;
  overflow:visible!important;
  white-space:normal!important;
  text-overflow:clip!important;
  line-height:1.18!important;
}
.order-meta-primary{
  display:block;
  min-width:0;
