}
.order-pzn-copy{width:20px!important;height:20px!important;min-width:20px!important;margin:0!important}
.order-product-row{min-height:88px}

/* DHL is obligatory logistics, not a numbered product position. */
.presend-logistics .presend-num{visibility:hidden}
