    background:
      linear-gradient(90deg,transparent 0 18px,var(--order-margin) 18px 19px,transparent 19px),
      repeating-linear-gradient(to bottom,transparent 0 28px,var(--order-rule) 28px 29px),
      rgba(255,252,245,.38)!important;
    background-attachment:local!important;
  }
}

