/* ===== v0.86 — quiet viewed states; expansion is geometry, not another color ===== */
:root{
  --v86-viewed: rgba(247,241,225,.38);
  --v86-viewed-history: rgba(247,241,225,.48);
  --v86-branch: #c7b58e;
}

/* A previously inspected product leaves only a very faint, session-only trace. */
.product-row.viewed:not(.selected):not(:hover){
  background:var(--v86-viewed)!important;
}

/* Expanded is NOT a persistent fill anymore. Viewed trace may remain, but no extra color. */
.product-row.expanded:not(.selected):not(:hover){
  background:var(--v86-viewed)!important;
}

/* Expansion is represented as a small notebook/tree branch into the detail block. */
.product-row.expanded:not(.selected) .product-expand{
  position:relative;
  margin-left:18px!important;
  padding-left:18px!important;
  border-left:1.5px solid var(--v86-branch)!important;
}
.product-row.expanded:not(.selected) .product-expand::before{
  content:"";
  position:absolute;
  left:-1.5px;
  top:13px;
  width:13px;
  height:1.5px;
  background:var(--v86-branch);
}

/* Cart remains the only strong persistent row state. */
.product-row.selected,
.product-row.selected.viewed,
.product-row.selected.expanded,
.product-row.selected:hover{
  background:linear-gradient(90deg,#ffe7a0,#fff0bd 55%,#ffdf85)!important;
}

/* Order sheet: expansion itself does not leave a color behind. Only the pointer highlights. */
.order-product-row.order-expanded,
.order-product-row.order-expanded:focus-within{
  background:transparent!important;
  box-shadow:none!important;
  transform:none!important;
}
@media (hover:hover) and (pointer:fine){
  .order-product-row:hover,
  .order-product-row.order-expanded:hover,
  .order-product-row.order-expanded:focus-within:hover{
    background:#f8edcf!important;
  }
}
@media (hover:none), (pointer:coarse), (max-width:760px){
  .order-product-row.order-expanded,
  .order-product-row.order-expanded:hover,
  .order-product-row.order-expanded:focus-within{
    background:transparent!important;
  }
}

/* Recent: product entries use the very same faint semantic trace. */
.flow-history-menu .flow-history-list button.history-product{
  background:var(--v86-viewed-history)!important;
}
.flow-history-menu .flow-history-list button.history-product:hover{
