/* ===== v1.56 — VARIANT 1: CLEAN SERVICE =====
   White working surface, restrained green service accent,
   red only for RX / destructive warnings, warm tint only in the brand header. */

:root{
  --rxde-bg:#f6f8f7;
  --rxde-surface:#ffffff;
  --rxde-surface-soft:#fbfcfb;
  --rxde-border:#dfe7e4;
  --rxde-border-strong:#cfdad6;
  --rxde-text:#1b2a2e;
  --rxde-muted:#6f7f83;
  --rxde-green:#2f665d;
  --rxde-green-2:#3f796f;
  --rxde-green-soft:#edf5f2;
  --rxde-red:#c84e4a;
  --rxde-warm:#fffaf2;
  --rxde-shadow:0 3px 12px rgba(30,55,49,.055);
}

/* ---------- PAGE / HEADER ---------- */

body{
  background-color:var(--rxde-bg)!important;
}

.site-shell,
.page-shell,
main{
  background:var(--rxde-surface)!important;
}

/* Keep a small amount of brand warmth only at the very top. */
.site-header,
.header-shell,
.top-header{
  background:linear-gradient(180deg,#fffdf9 0%,#fffaf3 100%)!important;
  border-bottom:1px solid rgba(214,205,186,.42)!important;
}

/* Lighter logo frame; preserve the mark, reduce visual weight. */
.brand-mark,
.logo-rx,
.rx-logo-box{
  border-width:1.4px!important;
  border-color:#db615d!important;
  border-radius:11px!important;
  box-shadow:none!important;
}

/* ---------- SEARCH ---------- */

.search-wrap,
.search-box{
  background:#fff!important;
  border:1px solid var(--rxde-border-strong)!important;
  box-shadow:0 1px 4px rgba(34,61,55,.035)!important;
}

.search-wrap:focus-within,
.search-box:focus-within{
  border-color:#8db2a9!important;
  box-shadow:0 0 0 3px rgba(63,121,111,.10)!important;
}

.search-input,
#searchInput{
  color:var(--rxde-text)!important;
}

.search-input::placeholder,
#searchInput::placeholder{
  color:#879397!important;
}

/* ---------- NAV / CATEGORIES ---------- */

.category-tabs,
.cat-tabs,
.nav-tabs,
.notebook-tabs{
  background:#fff!important;
  border-top:1px solid var(--rxde-border)!important;
  border-bottom:1px solid var(--rxde-border)!important;
  box-shadow:none!important;
