#productList .full-product-link{
  color:var(--rxde-green)!important;
}

/* ---------- QUANTITY / PRICE ---------- */

.qty-stepper,
.order-qty,
.suggest-stepper{
  border:1px solid var(--rxde-border-strong)!important;
  background:#fff!important;
  box-shadow:none!important;
}

.qty-stepper button,
.order-qty button,
.suggest-stepper button{
  background:#f8faf9!important;
  color:#24373b!important;
  border-color:var(--rxde-border)!important;
}

.qty-stepper input,
.order-qty input,
.suggest-stepper b{
  background:#fff!important;
  color:#16272b!important;
}

/* Selected state: one soft service accent, not multiple competing greens. */








/* Handwritten ×1 remains the personality detail. */
.cart-qty-mark,
.product-qty-mark,
.handwritten-qty{
  color:#28705f!important;
}

/* ---------- TOP ORDER DOCK ---------- */

#desktopOrderDock,
.desktop-order-dock,
