}

.order-sheet .sheet-header,
#orderSheet .sheet-header{
  background:linear-gradient(180deg,#fffdf9,#fffaf3)!important;
}

/* Clean cards already introduced in v1.55; refine to variant 1 palette. */
#orderLines .order-static-card{
