/* --------------------------------------------------------------------------
   1) Catalogue card hover: paint ONLY.
   Nothing inside the card is allowed to move, scale, translate or resize.
   -------------------------------------------------------------------------- */




/* Kill every old descendant hover translation/scale. */


/* Never transition geometry inside product cards. */


/* Pointer means clickable. Price is the only intentionally non-clickable field. */






/* --------------------------------------------------------------------------
   2) ONE standard static quantity control everywhere.
   Same visual language as the order sheet: pale minus, white qty, blue plus.
   No changing border, radius, scale, position or dimensions on hover/active.
   -------------------------------------------------------------------------- */
.qty-stepper,
.order-qty,
.suggest-stepper,
.pq-stepper{
  box-sizing:border-box!important;
  overflow:hidden!important;
  border:1px solid #a9c6d9!important;
  border-radius:9px!important;
  background:#fff!important;
  box-shadow:none!important;
  transform:none!important;
  translate:none!important;
  scale:1!important;
  transition:none!important;
}

/* Keep each context's existing width/height; only visual styling is unified. */
.qty-stepper button,
.qty-stepper input,
.order-qty button,
.order-qty input,
.suggest-stepper button,
.suggest-stepper b,
.pq-stepper button,
.pq-stepper input{
  box-sizing:border-box!important;
  margin:0!important;
  border-radius:0!important;
  transform:none!important;
  translate:none!important;
  scale:1!important;
  box-shadow:none!important;
  transition:background-color .12s ease,color .12s ease!important;
}

/* Minus */
.qty-stepper button:first-child,
.order-qty button:first-child,
.suggest-stepper button:first-child,
.pq-stepper button:first-child{
  background:#eef6ff!important;
  color:#245a83!important;
  border:0!important;
  border-right:1px solid #d4e1e9!important;
}

/* Quantity center */
.qty-stepper input,
.order-qty input,
.suggest-stepper b,
.pq-stepper input{
  background:#fff!important;
  color:#16272b!important;
  border-top:0!important;
  border-bottom:0!important;
  border-left:0!important;
  border-right:0!important;
  font-variant-numeric:tabular-nums!important;
}

/* Plus */
.qty-stepper button:last-child,
.order-qty button:last-child,
.suggest-stepper button:last-child,
.pq-stepper button:last-child{
  background:#2f7fbf!important;
  color:#fff!important;
  border:0!important;
  border-left:1px solid #286fa8!important;
  box-shadow:none!important;
}

/* Hover = color only. Absolutely no movement, border change, resize or shadow. */
.qty-stepper button:hover:not(:disabled),
.order-qty button:hover:not(:disabled),
.suggest-stepper button:hover:not(:disabled),
.pq-stepper button:hover:not(:disabled){
  transform:none!important;
  translate:none!important;
  scale:1!important;
  box-shadow:none!important;
  border-color:inherit!important;
}
.qty-stepper button:first-child:hover:not(:disabled),
.order-qty button:first-child:hover:not(:disabled),
.suggest-stepper button:first-child:hover:not(:disabled),
.pq-stepper button:first-child:hover:not(:disabled){
  background:#e6f1fa!important;
}
.qty-stepper button:last-child:hover:not(:disabled),
.order-qty button:last-child:hover:not(:disabled),
.suggest-stepper button:last-child:hover:not(:disabled),
.pq-stepper button:last-child:hover:not(:disabled){
  background:#2a74af!important;
}

/* Press/focus also preserves exact geometry. */
.qty-stepper button:active,
.order-qty button:active,
.suggest-stepper button:active,
.pq-stepper button:active,
.qty-stepper button:focus-visible,
.order-qty button:focus-visible,
.suggest-stepper button:focus-visible,
.pq-stepper button:focus-visible,
.qty-stepper input:focus,
.order-qty input:focus,
.pq-stepper input:focus{
  transform:none!important;
  translate:none!important;
  scale:1!important;
  outline:none!important;
  box-shadow:none!important;
}

/* Disabled minus stays in the same place and size. */
.qty-stepper button:disabled,
.order-qty button:disabled,
.suggest-stepper button:disabled,
.pq-stepper button:disabled{
  background:#f3f6f7!important;
  color:#aab6bc!important;
  opacity:1!important;
  cursor:default!important;
}

