}

/* Search and mini use the same regular black service text. */



/* ==========================================================================
   V1.152 — TIGHT STRIP + FULL WIDTH + SEARCH FIX
   - Service strip reduced to text-height + 1px top/bottom.
   - RUB is primary everywhere in cards; EUR is secondary hint.
   - Search suggestion side layout fixed (no price overlap).
   - Related strip spans full width.
   ========================================================================== */

:root{
  --rxde-service-strip-bg:#d9edf8;
  --rxde-service-strip-text:#111111;
  --rxde-service-strip-font:8px;
  --rxde-service-strip-line:10px;
  --rxde-service-strip-h:12px;     /* line-height 10 + 1px top + 1px bottom */
}

/* ------------------ Unified price hierarchy in all product cards ------------------ */



/* Search rows: explicit three-zone layout, enough room for price + stepper */
#searchSuggest .suggest-row{
  display:grid!important;
  grid-template-columns:78px minmax(0,1fr) 240px!important;
  grid-template-areas:
    "photo main side"
    "picked picked picked"!important;
  align-items:start!important;
  gap:10px 12px!important;
  min-height:96px!important;
  padding:10px 12px 0 12px!important;
}
#searchSuggest .suggest-photo{grid-area:photo!important;}
#searchSuggest .suggest-main{grid-area:main!important; min-width:0!important;}
#searchSuggest .suggest-side{
  grid-area:side!important;
  display:grid!important;
  grid-template-columns:1fr 106px!important;
  align-items:start!important;
  justify-items:end!important;
  gap:10px!important;
  width:100%!important;
  padding-top:2px!important;
  min-width:0!important;
}
#searchSuggest .suggest-price{
  display:flex!important;
  flex-direction:column!important;
  align-items:flex-end!important;
  justify-content:flex-start!important;
  min-width:82px!important;
  text-align:right!important;
}
#searchSuggest .suggest-stepper{
  justify-self:end!important;
  align-self:start!important;
}

/* Compact/minicards: keep strip flush to bottom edge */



/* Main mini card: strip should touch the bottom as one full bar */



/* Search row: strip spans the whole row width */
#searchSuggest .suggest-row{
  overflow:hidden!important;
}
#searchSuggest .suggest-picked{
  grid-area:picked!important;
  width:calc(100% + 24px)!important;
  margin:0 -12px 0 -12px!important;
  border-top:1px solid rgba(169,202,220,.75)!important;
  justify-content:flex-end!important;
}

/* Quick view main card: full-width bottom service strip, tight height */
#productQuickBody .pq-picked{
  display:flex!important;
  width:calc(100% + 48px)!important;
  margin:10px -24px -24px -24px!important;
  padding:1px 18px!important;
  justify-content:flex-end!important;
  border-top:1px solid rgba(169,202,220,.75)!important;
  border-bottom-left-radius:24px!important;
  border-bottom-right-radius:24px!important;
}
#productQuickBody .pq-bottom{
  display:grid!important;
  grid-template-columns:minmax(0,1fr) auto!important;
  align-items:end!important;
  gap:14px!important;
}
#productQuickBody .pq-price{
  align-items:flex-start!important;
  justify-self:start!important;
  text-align:left!important;
}
#productQuickBody .pq-stepper{
  justify-self:end!important;
  align-self:end!important;
}

/* Related cards: strip must occupy the entire bottom row */
#productQuickRelated .pq-float-related{
  display:grid!important;
  grid-template-columns:76px minmax(0,1fr)!important;
  grid-template-rows:auto auto auto!important;
  gap:10px 12px!important;
  overflow:hidden!important;
}
#productQuickRelated .pq-float-related-picked{
  grid-column:1 / -1!important;
  width:calc(100% + 24px)!important;
  margin:0 -12px -10px -12px!important;
  padding:1px 12px!important;
  border-top:1px solid rgba(169,202,220,.75)!important;
  justify-content:flex-end!important;
}
#productQuickRelated .pq-float-related-price{
  align-items:flex-start!important;
  text-align:left!important;
}
#productQuickRelated .pq-float-related-price strong{
  font-size:15px!important;
}
#productQuickRelated .pq-float-related-price span{
  font-size:10px!important;
}
#productQuickRelated .pq-float-related-picked.selected{
  background:var(--rxde-service-strip-bg)!important;
  color:#111!important;
  font-weight:400!important;
}

/* Make service text regular black everywhere */


/* Safety: keep stepper consistent and not oversized in the related/search views */
#searchSuggest .suggest-stepper,
#productQuickBody .pq-stepper,
#productQuickRelated .pq-float-related-stepper{
  transform:none!important;
  zoom:1!important;
}

/* If some older rule makes the strip look dark / bold, force the light main-page style */
#searchSuggest .suggest-picked.selected,
#productQuickBody .pq-picked.selected,
#productQuickRelated .pq-float-related-picked.selected{
  background:#d9edf8!important;
  color:#111!important;
}


/* ==========================================================================
   V1.152 — ONE SERVICE STRIP STANDARD
   Main catalog strip is the reference:
   same height, fill, typography and 1px separator everywhere.
   Only the numeric quantity and amount are bold.
   ========================================================================== */

:root{
  --rxde-service-strip-bg:#d9edf8;
  --rxde-service-strip-border:#a9cadc;
  --rxde-service-strip-text:#111;
  --rxde-service-strip-font:8px;
  --rxde-service-strip-line:10px;
  --rxde-service-strip-h:12px;
}

/* Shared visual language */




/* Main page is the reference: full width, flush to lower edge */



/* Search suggestion: full row strip and keep price + controls readable. */
#searchSuggest .suggest-row{
  position:relative!important;
  overflow:hidden!important;
  padding-bottom:var(--rxde-service-strip-h)!important;
}
#searchSuggest .suggest-picked{
  position:absolute!important;
  left:0!important;
  right:0!important;
  bottom:0!important;
  width:100%!important;
}
#searchSuggest .suggest-side{
  display:grid!important;
  grid-template-columns:minmax(88px,1fr) 106px!important;
  align-items:start!important;
  gap:10px!important;
}
#searchSuggest .suggest-price{
  display:flex!important;
  visibility:visible!important;
  opacity:1!important;
  min-width:88px!important;
  align-items:flex-end!important;
  text-align:right!important;
}
#searchSuggest .suggest-price b{
  display:block!important;
  color:#123f63!important;
  font-size:16px!important;
  line-height:1.05!important;
  font-weight:760!important;
}
#searchSuggest .suggest-price small{
  display:block!important;
  color:#728897!important;
  font-size:10px!important;
  line-height:1.05!important;
  font-weight:500!important;
}

/* Medium / Quick View:
   V1.152 lost the strip because it was still participating in the two-column body grid.
   Make it a real full-width lower edge of the floating card. */
.product-quick-sheet{
  position:relative!important;
  padding-bottom:calc(22px + var(--rxde-service-strip-h))!important;
  overflow:hidden!important;
}
#productQuickBody .pq-picked{
  position:absolute!important;
  left:0!important;
  right:0!important;
  bottom:0!important;
  width:100%!important;
  grid-column:auto!important;
  border-bottom-left-radius:22px!important;
  border-bottom-right-radius:22px!important;
}
#productQuickBody .pq-price strong{
  font-size:18px!important;
  line-height:1.05!important;
  font-weight:760!important;
  color:#123f63!important;
}
#productQuickBody .pq-price span{
  font-size:10px!important;
  line-height:1.05!important;
  font-weight:500!important;
  color:#728897!important;
  margin-top:2px!important;
}

/* Related cards:
   old rules left the service strip constrained to the info column / inset.
   Pin it to the whole card width. */
#productQuickRelated .pq-float-related{
  position:relative!important;
  overflow:hidden!important;
  padding-bottom:calc(10px + var(--rxde-service-strip-h))!important;
}
#productQuickRelated .pq-float-related-picked{
  position:absolute!important;
  left:0!important;
  right:0!important;
  bottom:0!important;
  width:100%!important;
  max-width:none!important;
  grid-column:auto!important;
  margin:0!important;
  border-bottom-left-radius:16px!important;
  border-bottom-right-radius:16px!important;
}
#productQuickRelated .pq-float-related-price b{
  display:block!important;
  color:#123f63!important;
  font-size:15px!important;
  line-height:1.05!important;
  font-weight:760!important;
}
#productQuickRelated .pq-float-related-price small{
  display:block!important;
  color:#728897!important;
  font-size:10px!important;
  line-height:1.05!important;
  font-weight:500!important;
  margin-top:2px!important;
}

/* Mobile keeps exactly the same strip thickness. */
@media(max-width:900px){
  .product-quick-sheet{
    padding-bottom:calc(14px + var(--rxde-service-strip-h))!important;
  }
}


/* ==========================================================================
   V1.152 — thinner service strip + regular type + direct jump to cart
   Main catalog, search cards, medium quick card and related cards
   all use ONE visual standard based on the preferred smaller strip.
   ========================================================================== */
:root{
  --rxde-service-strip-bg-v151:#d9edf8;
  --rxde-service-strip-text-v151:#111111;
  --rxde-service-strip-border-v151:#a9cadc;
  --rxde-service-strip-h-v151:12px;
  --rxde-service-strip-font-v151:8.4px;
  --rxde-service-strip-lh-v151:10px;
}





/* Ensure the strip is really flush to the card edge. */


/* Reserve only the smaller strip height. */
#searchSuggest .suggest-row{
  padding-bottom:var(--rxde-service-strip-h-v151)!important;
}
.product-quick-sheet{
  padding-bottom:calc(22px + var(--rxde-service-strip-h-v151))!important;
}
#productQuickRelated .pq-float-related{
  padding-bottom:calc(10px + var(--rxde-service-strip-h-v151))!important;
}

/* Main catalogue card also follows the tighter strip proportion. */


/* Click affordance: body of a catalogue card opens the card, strip jumps to cart. */


/* Keep product rows/preview rows using rubles as the visual priority everywhere. */
#searchSuggest .suggest-price b,
#productQuickRelated .pq-float-related-price b,
#productQuickBody .pq-price strong{
  font-weight:760!important;
  color:#123f63!important;
}
#searchSuggest .suggest-price small,
#productQuickRelated .pq-float-related-price small,
#productQuickBody .pq-price span{
  font-weight:500!important;
  color:#728897!important;
}

/* Search suggestion layout: guarantee enough room for price and stepper. */
#searchSuggest .suggest-side{
  display:grid!important;
  grid-template-columns:minmax(90px,1fr) 96px!important;
  align-items:start!important;
  justify-items:end!important;
  gap:10px!important;
}
#searchSuggest .suggest-price{
  min-width:90px!important;
  text-align:right!important;
  align-self:flex-start!important;
}

/* Quick card and related cards: use the same strip thickness/colour and keep it full width. */
#productQuickBody .pq-picked,
#productQuickRelated .pq-float-related-picked{
  max-width:none!important;
}

/* Related cards and main quick card should show strip across the entire width with same thickness. */
#productQuickRelated .pq-float-related-picked{
  left:0!important;right:0!important;bottom:0!important;
}
#productQuickBody .pq-picked{
  left:0!important;right:0!important;bottom:0!important;
}


/* ==========================================================================
   V1.152 — CLICKABLE FORM BADGES + CART FAMILY SEARCH
   ========================================================================== */

/* Catalogue form badge is a secondary action: click = filter current selection by form. */
#productList .form-badge[data-card-form-filter]{
  cursor:pointer!important;
  user-select:none!important;
  transition:border-color .12s ease,box-shadow .12s ease,background-color .12s ease!important;
}
#productList .form-badge[data-card-form-filter]:hover{
  border-color:#7faeca!important;
  box-shadow:0 1px 5px rgba(55,103,135,.16)!important;
}
#productList .form-badge[data-card-form-filter]:active{
  box-shadow:none!important;
}

/* Form row is deliberately compact and appears only after a form badge is used. */
#formFilterStrip.form-filter-strip{
  margin:4px 22px 7px!important;
  min-height:28px!important;
  padding:0!important;
}
#formFilterStrip .form-filter-scroll{
  gap:5px!important;
  padding:0!important;
}
#formFilterStrip .form-filter-chip{
  height:26px!important;
  padding:0 9px!important;
  border-radius:999px!important;
  font-size:11px!important;
  line-height:24px!important;
  font-weight:600!important;
}
#formFilterStrip .form-filter-chip b{
  font-size:9px!important;
  font-weight:700!important;
}
#formFilterStrip .form-filter-back{
  background:#fff!important;
  color:#35576b!important;
  border-color:#bcd3e1!important;
}

/* Magnifier / family search in the order sheet. */
.order-title-line{
  display:flex!important;
  align-items:center!important;
  gap:6px!important;
  min-width:0!important;
}
.order-expand-title{
  min-width:0!important;
  overflow:hidden!important;
  text-overflow:ellipsis!important;
  white-space:nowrap!important;
}
.order-family-search{
  flex:0 0 26px!important;
  width:26px!important;
  height:26px!important;
  min-width:26px!important;
  min-height:26px!important;
  padding:0!important;
  margin-left:2px!important;
  display:inline-flex!important;
  align-items:center!important;
  justify-content:center!important;
  border:1px solid #c8d8df!important;
  border-radius:50%!important;
  background:#fff!important;
