  #formFilterStrip .form-filter-chip{height:25px!important;font-size:10.5px!important;padding:0 8px!important}
  .order-family-search{width:30px!important;height:30px!important;min-width:30px!important;min-height:30px!important}
}

/* ==========================================================================
   V1.153 — LOCAL FORM COMPARISON + RETURN PATH + TIGHTER SERVICE STRIP
   ========================================================================== */
:root{
  --rxde-service-strip-h-v153:9px;
  --rxde-service-strip-font-v153:7.2px;
  --rxde-service-strip-lh-v153:8px;
}

/* The selected/service line is intentionally thinner than V1.152. */



#searchSuggest .suggest-row{padding-bottom:var(--rxde-service-strip-h-v153)!important}
.product-quick-sheet{padding-bottom:calc(22px + var(--rxde-service-strip-h-v153))!important}
#productQuickRelated .pq-float-related{padding-bottom:calc(10px + var(--rxde-service-strip-h-v153))!important}

/* Form click opens a local chooser without reflowing or scrolling the catalogue. */
.form-chooser-popover{
  position:fixed!important;z-index:1600!important;
  padding:10px!important;border:1px solid #b9ceda!important;border-radius:12px!important;
  background:#fffdf8!important;box-shadow:0 14px 36px rgba(34,61,76,.22)!important;
  font-family:var(--rxde-ui-font)!important;color:#1b3645!important;
}
.form-chooser-popover[hidden]{display:none!important}
.form-chooser-head{position:relative!important;display:flex!important;flex-direction:column!important;gap:2px!important;padding:0 32px 8px 2px!important;border-bottom:1px solid #e3ecef!important}
.form-chooser-head strong{font-size:13px!important;line-height:16px!important;font-weight:800!important}
.form-chooser-head span{font-size:10.5px!important;line-height:14px!important;color:#6a7e89!important;white-space:nowrap!important;overflow:hidden!important;text-overflow:ellipsis!important}
.form-chooser-head button{position:absolute!important;right:0!important;top:-2px!important;width:28px!important;height:28px!important;border:0!important;border-radius:50%!important;background:transparent!important;color:#667b86!important;font-size:20px!important;line-height:28px!important;cursor:pointer!important}
.form-chooser-head button:hover{background:#edf5f8!important}
.form-chooser-actions{display:flex!important;flex-wrap:wrap!important;gap:6px!important;padding:9px 0 4px!important}
.form-choice{height:29px!important;padding:0 10px!important;border:1px solid #c8dbe5!important;border-radius:999px!important;background:#fff!important;color:#31586d!important;font-size:11px!important;font-weight:650!important;cursor:pointer!important}
.form-choice:hover{background:#eef7fb!important;border-color:#8fb8cf!important}
.form-choice b{margin-left:4px!important;font-size:9px!important;opacity:.68!important}
.form-choice.all{border-color:#9dbfce!important;background:#f5fbfd!important}
.form-chooser-note{padding:4px 2px 0!important;font-size:9.2px!important;color:#7b8b93!important}

/* Persistent compare context: user always knows where they came from and how to go back. */
#formFilterStrip.form-filter-strip{
  flex-wrap:wrap!important;align-items:center!important;column-gap:7px!important;row-gap:5px!important;
}
#formFilterStrip .form-filter-return{
  flex:0 0 auto!important;height:27px!important;padding:0 10px!important;
  border:1px solid #aac7d6!important;border-radius:8px!important;background:#f5fbfd!important;
  color:#275772!important;font-size:10.8px!important;font-weight:700!important;cursor:pointer!important;
}
#formFilterStrip .form-filter-return:hover{background:#e9f5fa!important;border-color:#7faeca!important}
#formFilterStrip .form-filter-context{
  flex:1 1 240px!important;min-width:0!important;font-size:10.5px!important;line-height:14px!important;
  color:#647883!important;white-space:nowrap!important;overflow:hidden!important;text-overflow:ellipsis!important;
}
#formFilterStrip .form-filter-context b{color:#294b5c!important;font-weight:750!important}
#formFilterStrip .form-filter-scroll{flex:1 1 100%!important;width:100%!important}

@media(max-width:760px){
  .form-chooser-popover{padding:9px!important;border-radius:11px!important}
  #formFilterStrip .form-filter-return{height:26px!important;padding:0 8px!important;font-size:10px!important}
  #formFilterStrip .form-filter-context{flex-basis:180px!important;font-size:9.8px!important}
  .product-quick-sheet{padding-bottom:calc(14px + var(--rxde-service-strip-h-v153))!important}
}

