  animation:rxdeFlashBlueV155 1.35s ease-out 1!important;
}
#orderLines [data-pzn].bridge-highlight-order-v155{
  position:relative!important;z-index:6!important;
  animation:rxdeFlashBlueV155 1.35s ease-out 1!important;
}

