  display:grid!important;
  grid-template-columns:92px minmax(0,1fr)!important;
  grid-template-rows:minmax(91px,auto) 42px!important;
  gap:5px 12px!important;
  padding:10px 12px 9px!important;
  overflow:hidden!important;
}
