/* ========================================================================== 
   V1.201 — contact-first order entry
   ========================================================================== */
/* Hover mini-list is intentionally removed. Click opens the order sheet. */
.dock-hover-preview{display:none!important}

/* When the cart is empty, the order dock becomes a calm contact entry point. */
.desktop-order-dock.contact-ready,
.quick-order-dock.contact-ready{
  overflow:hidden!important;
  isolation:isolate!important;
}
.desktop-order-dock.contact-ready::after,
.quick-order-dock.contact-ready::after{
  content:"";
  position:absolute;
  inset:1px;
  z-index:-1;
  border-radius:inherit;
  background:linear-gradient(105deg,transparent 22%,rgba(72,157,211,.12) 48%,transparent 74%);
  transform:translateX(-125%);
  animation:rxdeContactBreath 7.8s ease-in-out infinite;
  pointer-events:none;
}
@keyframes rxdeContactBreath{
  0%,70%,100%{transform:translateX(-125%);opacity:0}
  76%{opacity:1}
  88%{transform:translateX(125%);opacity:.95}
  94%{opacity:0}
}
.desktop-order-dock.contact-ready .order-status-meta,
.quick-order-dock.contact-ready .order-status-meta{color:#315e76!important;font-weight:750!important}
.desktop-order-dock.contact-ready .order-status-total,
.quick-order-dock.contact-ready .order-status-total{color:#1b6f9f!important;font-size:13px!important}

.order-empty.contact-empty{
  display:grid!important;
  gap:5px!important;
  padding:22px!important;
  border:1px dashed #c7dbe6!important;
  border-radius:14px!important;
  background:#f8fcfe!important;
  text-align:left!important;
}
.order-empty.contact-empty b{color:#244c62;font-size:13px}
.order-empty.contact-empty span{color:#6a7e89;font-size:11.5px;line-height:1.45}

.preinvoice-question{
  display:grid;
  grid-template-columns:20px minmax(0,1fr);
  gap:9px;
  align-items:start;
  margin-top:11px;
  padding:10px 11px;
  border:1px solid #d7e4e9;
  border-radius:11px;
  background:#f8fbfc;
