/* ========================================================================== 
   V1.202 — persistent cart totals + temporary contact prompt
   ========================================================================== */
.desktop-order-dock.cart-promo-enabled,
.quick-order-dock.cart-promo-enabled{position:relative!important;overflow:hidden!important;isolation:isolate!important}
.desktop-order-dock.cart-promo-enabled .order-status-copy,
.quick-order-dock.cart-promo-enabled .order-status-copy{transition:opacity .18s ease,filter .18s ease!important}
.desktop-order-dock.cart-promo-enabled::before,
.quick-order-dock.cart-promo-enabled::before{
  content:attr(data-promo);position:absolute!important;inset:2px 5px!important;z-index:5!important;
  display:flex!important;align-items:center!important;justify-content:center!important;text-align:center!important;
  border-radius:inherit!important;color:#195f88!important;font-size:11px!important;font-weight:800!important;line-height:1.1!important;
  letter-spacing:.01em!important;opacity:0!important;transform:translateY(3px) scale(.98)!important;
  transition:opacity .18s ease,transform .18s ease!important;pointer-events:none!important;
}
.desktop-order-dock.cart-promo-enabled::after,
.quick-order-dock.cart-promo-enabled::after{
  content:""!important;position:absolute!important;inset:1px!important;z-index:4!important;border-radius:inherit!important;
  background:linear-gradient(105deg,rgba(255,255,255,0) 12%,rgba(97,178,224,.09) 34%,rgba(145,211,245,.28) 52%,rgba(97,178,224,.09) 70%,rgba(255,255,255,0) 90%)!important;
  transform:translateX(-125%)!important;opacity:0!important;pointer-events:none!important;
}
.desktop-order-dock.cart-promo-active .order-status-copy,
.quick-order-dock.cart-promo-active .order-status-copy{opacity:.24!important;filter:blur(.15px)!important}
.desktop-order-dock.cart-promo-active::before,
.quick-order-dock.cart-promo-active::before{opacity:1!important;transform:translateY(0) scale(1)!important}
.desktop-order-dock.cart-promo-active::after,
.quick-order-dock.cart-promo-active::after{animation:rxdeCartAttentionSweep 1.15s ease both!important}
@keyframes rxdeCartAttentionSweep{0%{transform:translateX(-125%);opacity:0}22%{opacity:1}100%{transform:translateX(125%);opacity:0}}
.desktop-order-dock.cart-promo-enabled:hover .order-status-copy,
.quick-order-dock.cart-promo-enabled:hover .order-status-copy{opacity:1!important;filter:none!important}
.desktop-order-dock.cart-promo-enabled:hover::before,
.quick-order-dock.cart-promo-enabled:hover::before,
.desktop-order-dock.cart-promo-enabled:hover::after,
.quick-order-dock.cart-promo-enabled:hover::after{opacity:0!important;animation:none!important}
