/* ========================================================================== 
   V2.22 — row-anchored sticky package.
   The package remains in normal document flow and becomes sticky at the top.
   Therefore showing/hiding it never changes catalogue geometry and cannot
   create a scroll/layout feedback loop.
   ========================================================================== */
#stickyStack.sticky-stack{
  position:sticky!important;
  left:auto!important;right:auto!important;top:0!important;bottom:auto!important;
  width:100%!important;max-width:none!important;
  margin:0!important;padding:0!important;
  z-index:2400!important;
  transform:translate3d(0,0,0)!important;
  transition:transform .14s cubic-bezier(.2,.72,.25,1)!important;
  will-change:transform!important;
  isolation:isolate!important;
  overflow:visible!important;
  overflow-anchor:none!important;
  background:#fff!important;
  box-shadow:0 2px 8px rgba(41,72,86,.08)!important;
}
#stickyStack > #appHeader,
#stickyStack > #flowNav,
#stickyStack > #flowNav:not([hidden]){
  position:relative!important;
  left:auto!important;right:auto!important;top:auto!important;bottom:auto!important;
  width:100%!important;max-width:none!important;
  transform:none!important;transition:none!important;
}
#stickyStack > #appHeader{z-index:2!important}
#stickyStack > #flowNav{z-index:1!important}

body.mobile-header-scrolling #stickyStack.sticky-stack,
body.mobile-header-hidden #stickyStack.sticky-stack{
